func getDemographicsForLocation(_ location: CLLocationCoordinate2D) -> [String] {
    // Use a demographic API to get user's demographics
    let demographicAPI = DemographicAPI()
    let demographics = demographicAPI.getDemographicsForLocation(location)

    return demographics
}

